import test from 'node:test';import assert from 'node:assert/strict';import {createApprovalRequest,decideApproval,canActorApprove} from '../src/index.mjs';
test('multi-step approval',()=>{let r=createApprovalRequest({id:'a1',subjectRef:{kind:'purchase',id:'p1'},requestedBy:'u0',steps:[{id:'manager',approverIds:['u1']},{id:'director',approverIds:['u2']}]});assert.equal(canActorApprove(r,'u1'),true);r=decideApproval(r,{actorId:'u1',decision:'approved',at:'2026-09-14T10:00:00Z'});assert.equal(r.currentStepId,'director');r=decideApproval(r,{actorId:'u2',decision:'approved',at:'2026-09-14T11:00:00Z'});assert.equal(r.status,'approved')});
test('rejects impossible or invalid approval thresholds',()=>{const base={id:'a1',subjectRef:{kind:'purchase',id:'p1'},requestedBy:'u0'};assert.throws(()=>createApprovalRequest({...base,steps:[{id:'manager',approverIds:['u1'],minApprovals:2}]}),/cannot exceed/);assert.throws(()=>createApprovalRequest({...base,steps:[{id:'manager',minApprovals:0}]}),/positive integer/);assert.throws(()=>createApprovalRequest({...base,steps:[{id:'same'},{id:'same'}]}),/unique/)});
